CREATE OR REPLACE FUNCTION public.approve_and_post_expense_bill(p_bill_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE b public.expense_bills%ROWTYPE; j uuid; BEGIN SELECT * INTO b FROM public.expense_bills WHERE id=p_bill_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Bill not available'; END IF; IF NOT (public.user_has_tenant(auth.uid(),b.tenant_id) OR public.is_super_admin(auth.uid())) OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Not allowed to approve this bill'; END IF; IF b.approval_status='posted' THEN RETURN b.journal_entry_id; END IF; IF b.approval_status NOT IN ('draft','pending_review','approved') THEN RAISE EXCEPTION 'Bill cannot be approved'; END IF; UPDATE public.expense_bills SET approval_status='approved',approved_by=COALESCE(approved_by,auth.uid()),approved_at=COALESCE(approved_at,now()) WHERE id=b.id; j:=public.post_expense_bill(b.id); RETURN j; END $$;
GRANT EXECUTE ON FUNCTION public.approve_and_post_expense_bill(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.approve_expense_category_accounts(p_tenant uuid,p_links jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE x jsonb; BEGIN IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin approval required'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(p_links) LOOP IF NOT EXISTS(SELECT 1 FROM public.chart_of_accounts WHERE id=(x->>'account_id')::uuid AND tenant_id=p_tenant) THEN RAISE EXCEPTION 'Account not available'; END IF; UPDATE public.expense_categories SET default_account_id=(x->>'account_id')::uuid WHERE id=(x->>'category_id')::uuid AND tenant_id=p_tenant AND default_account_id IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Category changed — refresh first'; END IF; END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.approve_expense_category_accounts(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.merge_expense_vendor(p_tenant uuid,p_from uuid,p_into uuid) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; BEGIN IF p_from=p_into OR NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin approval required'; END IF; PERFORM id FROM public.suppliers WHERE tenant_id=p_tenant AND id IN(p_from,p_into) ORDER BY id FOR UPDATE; IF (SELECT count(*) FROM public.suppliers WHERE tenant_id=p_tenant AND id IN(p_from,p_into))<>2 THEN RAISE EXCEPTION 'Vendor not available'; END IF; IF EXISTS(SELECT 1 FROM public.expense_bills WHERE tenant_id=p_tenant AND supplier_id=p_from AND approval_status IN('posted','reversed')) THEN RAISE EXCEPTION 'Booked bills must retain their vendor; merge cannot change locked records'; END IF; UPDATE public.expense_bills SET supplier_id=p_into,supplier_account_id=NULL WHERE tenant_id=p_tenant AND supplier_id=p_from; GET DIAGNOSTICS n=ROW_COUNT; UPDATE public.expense_recurring_rules SET supplier_id=p_into WHERE tenant_id=p_tenant AND supplier_id=p_from; UPDATE public.expense_vendor_statements SET supplier_id=p_into WHERE tenant_id=p_tenant AND supplier_id=p_from AND approval_status NOT IN('posted','reversed'); INSERT INTO public.audit_log(tenant_id,user_id,action,table_name,record_id,new_data) VALUES(p_tenant,auth.uid(),'merge_expense_vendor','suppliers',p_from,jsonb_build_object('into',p_into,'bills_relinked',n)); RETURN n; END $$;
GRANT EXECUTE ON FUNCTION public.merge_expense_vendor(uuid,uuid,uuid) TO authenticated;